@font-face{font-family:"Instrument Serif";src:url(/assets/fonts/iserif-400.woff2) format("woff2");font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:"Instrument Serif";src:url(/assets/fonts/iserif-400i.woff2) format("woff2");font-weight:400;font-style:italic;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url(/assets/fonts/instrument-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url(/assets/fonts/instrument-500.woff2) format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url(/assets/fonts/instrument-600.woff2) format("woff2");font-weight:600;font-display:swap}
:root{--white:#FFFFFF;
  --stone:#F2F0EB;
  --stone-2:#E4E1D9;
  --ink:#151C1F;
  --slate:#1C2629;
  --slate-2:#26343A;
  --ink-soft:#4A5357;
  --muted-dark:#A9B1AF;
  --brass:#7A5C2C;
  --brass-light:#CFAE72;
  --line:rgba(21,28,31,.13);
  --line-dark:rgba(255,255,255,.16);
  --serif:"Instrument Serif","Iowan Old Style","Palatino Linotype",Georgia,serif;
  --sans:"Instrument Sans","Helvetica Neue",Helvetica,Arial,sans-serif;
  --measure:66ch;
  --gutter:max(20px,4.5vw);
  --max:1400px;
  --s--2:.78rem;
  --s--1:clamp(.84rem,.82rem + .08vw,.9rem);
  --s-0:clamp(1rem,.98rem + .12vw,1.07rem);
  --s-1:clamp(1.18rem,1.1rem + .35vw,1.38rem);
  --s-2:clamp(1.55rem,1.35rem + .8vw,2.05rem);
  --s-3:clamp(2rem,1.6rem + 1.6vw,3rem);
  --s-4:clamp(2.5rem,1.8rem + 2.9vw,4.3rem);
  --s-5:clamp(2.9rem,1.9rem + 4.2vw,5.6rem);
  --ease:cubic-bezier(.2,.65,.2,1);}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--white);color:var(--ink);font-family:var(--sans);font-size:var(--s-0);line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
img,video{display:block;max-width:100%;height:auto}
a{color:inherit;text-decoration-thickness:1px;text-underline-offset:.25em}
a:hover{color:var(--brass)}
:focus-visible{outline:2px solid var(--brass);outline-offset:3px}
.dark :focus-visible,.band-dark :focus-visible,.hero :focus-visible,.banner :focus-visible,.cta-band :focus-visible,.site-foot :focus-visible,.utility :focus-visible,.aside-card :focus-visible,body.has-hero .site-head:not(.stuck) :focus-visible,.action-bar :focus-visible{outline-color:var(--brass-light)}
::selection{background:var(--brass-light);color:var(--ink)}
.skip{position:absolute;left:0;top:0;transform:translateY(-120%);background:var(--ink);color:#fff;padding:.7rem 1rem;z-index:300}
.skip:focus{left:1rem;top:1rem;transform:none}
h1,h2,h3{font-family:var(--serif);font-weight:400;line-height:1.06;letter-spacing:-.012em;margin:0 0 .45em;text-wrap:balance}
h1{font-size:var(--s-5)}
h2{font-size:var(--s-4)}
h4{font-family:var(--sans);font-size:var(--s-0);font-weight:600;margin:0 0 .4em}
p,ul,ol{margin:0 0 1.1em}
p,li,figcaption,.lede{text-wrap:pretty}
h1,h2,h3{font-kerning:normal;font-variant-ligatures:common-ligatures}
.lede{font-size:var(--s-1);line-height:1.55;max-width:48ch;color:var(--ink-soft)}
.muted{color:var(--ink-soft)}
.prose{max-width:var(--measure)}
.prose h2{font-size:var(--s-3);margin-top:1.6em;margin-bottom:.5em}
.prose h2 + p,.prose h3 + p{margin-top:0}
.prose p,.prose li{line-height:1.7}
.prose li{margin-bottom:.45em}
.wrap{max-width:var(--max);margin:0 auto;padding-left:var(--gutter);padding-right:var(--gutter)}
.section{padding-block:clamp(80px,10vw,150px)}
.section--tight{padding-block:clamp(44px,6vw,84px)}
.utility{background:var(--ink);color:#C9CFCC;font-size:var(--s--2);letter-spacing:.01em}
.utility .wrap{display:flex;justify-content:space-between;gap:16px;align-items:center;min-height:36px}
.utility a{text-decoration:none;color:#E8EBE9}
.utility a:hover{color:var(--brass-light)}
.utility .u-right{display:flex;gap:22px}
@media (max-width:760px){.utility .u-left{display:none}
.utility .wrap{justify-content:center}}
.site-head{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.97);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);transition:background .3s}
.site-head .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:82px}
body.has-hero .site-head{position:absolute;left:0;right:0;top:36px;background:linear-gradient(180deg,rgba(10,14,16,.55),rgba(10,14,16,0));border-bottom-color:rgba(255,255,255,.18);backdrop-filter:none;color:#fff}
body.has-hero .site-head.stuck{position:fixed;top:0;background:rgba(255,255,255,.97);color:var(--ink);border-bottom-color:var(--line)}
.logo{display:flex;align-items:center;gap:14px;text-decoration:none;color:inherit}
.logo svg{width:36px;height:36px;flex:0 0 36px}
.logo .ks{fill:var(--brass)}
.site-foot .logo .ks,body.has-hero .site-head:not(.stuck) .logo .ks{fill:var(--brass-light)}
.logo .wm{display:flex;flex-direction:column;line-height:1}
.logo .wm b{font-family:var(--serif);font-weight:400;font-size:1.72rem;letter-spacing:.005em;line-height:.9}
.logo .wm span{font-size:.58rem;font-weight:600;letter-spacing:.32em;text-transform:uppercase;opacity:.75;margin-top:7px}
.logo:hover{color:inherit}
.nav{display:flex;align-items:center;gap:clamp(16px,1.8vw,30px)}
.nav > ul{display:flex;gap:clamp(16px,1.8vw,30px);list-style:none;margin:0;padding:0;align-items:center}
.nav > ul > li{position:relative}
.nav > ul > li > a,.nav > ul > li > button{font:inherit;font-size:.8rem;font-weight:500;letter-spacing:.12em;text-transform:uppercase;text-decoration:none;background:none;border:0;color:inherit;cursor:pointer;padding:28px 0;display:block}
.nav .btn{font-size:.8rem;letter-spacing:.1em;text-transform:uppercase}
.mega{position:absolute;left:50%;top:100%;transform:translateX(-30%);width:min(860px,90vw);background:#fff;color:var(--ink);border:1px solid var(--line);box-shadow:0 24px 60px rgba(10,14,16,.14);display:grid;grid-template-columns:1fr 1fr 240px;gap:0 28px;padding:28px;opacity:0;visibility:hidden;transition:opacity .2s,visibility .2s}
.has-mega:hover .mega,.has-mega:focus-within .mega{opacity:1;visibility:visible}
.mega h4{font-size:var(--s--2);font-weight:600;color:var(--brass);margin:0 0 10px;letter-spacing:.02em}
.mega ul{list-style:none;margin:0 0 6px;padding:0}
.mega li a{display:block;padding:7px 0;text-decoration:none;font-size:.95rem;border-bottom:1px solid var(--line)}
.mega .mega-feature{background:var(--stone);display:block;text-decoration:none}
.mega .mega-feature img{width:100%;aspect-ratio:4/3;object-fit:cover}
.mega .mega-feature span{display:block;padding:12px 14px;font-size:.9rem;line-height:1.4}
.mega .mega-feature .mega-credit{display:block;padding:8px 14px 0;font-size:.75rem;line-height:1.35;color:var(--ink-soft)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.6em;min-height:48px;padding:.8em 1.5em;border:1px solid var(--ink);background:var(--ink);color:#fff;text-decoration:none;font-weight:500;font-size:.93rem;border-radius:0;cursor:pointer;font-family:var(--sans);transition:background .25s,border-color .25s,color .25s}
.btn:hover{background:var(--brass);border-color:var(--brass);color:#fff}
.btn:active{transform:translateY(1px)}
.btn.is-sending{opacity:.65;pointer-events:none}
.btn--ghost{background:transparent;color:inherit;border-color:currentColor}
.btn--ghost:hover{background:var(--ink);border-color:var(--ink);color:#fff}
body.has-hero .site-head:not(.stuck) .btn{background:#fff;color:var(--ink);border-color:#fff}
.menu-toggle{display:none;background:none;border:1px solid currentColor;color:inherit;min-height:44px;padding:0 16px;font:inherit;font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}
.menu-close{display:none}
@media (max-width:1100px){.site-head{backdrop-filter:none}
.menu-toggle{display:inline-block}
.nav{position:fixed;inset:0 0 0 auto;width:min(420px,100%);background:#fff;color:var(--ink);flex-direction:column;align-items:stretch;padding:96px var(--gutter) 40px;overflow-y:auto;transform:translateX(100%);transition:transform .35s var(--ease);box-shadow:-20px 0 60px rgba(0,0,0,.15)}
.nav.open{transform:none}
.nav > ul{flex-direction:column;align-items:stretch;gap:0}
.nav > ul > li > a,.nav > ul > li > button{padding:14px 0;border-bottom:1px solid var(--line);width:100%;text-align:left}
.mega{position:static;transform:none;width:auto;opacity:1;visibility:visible;box-shadow:none;border:0;padding:8px 0 12px;grid-template-columns:1fr;display:none}
.has-mega.open .mega{display:grid}
.mega .mega-feature{display:none}
.nav .btn{margin-top:20px;background:var(--ink)!important;color:#fff!important;border-color:var(--ink)!important}
.menu-close{display:block}}
.menu-close{position:absolute;top:26px;right:var(--gutter);background:none;border:1px solid var(--line);min-height:44px;padding:0 14px;font:inherit;cursor:pointer}
.hero-video.on{opacity:1;visibility:visible;transition:opacity 1.6s var(--ease)}
@media (prefers-reduced-motion:no-preference){@keyframes xfade{0%{opacity:0}2.4%{opacity:1}20%{opacity:1}22.4%{opacity:0}100%{opacity:0}}
@keyframes drift{0%{transform:scale(1.06)}22.4%{transform:scale(1)}100%{transform:scale(1)}}
@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
@keyframes cue{0%{transform:scaleY(0);transform-origin:top}45%{transform:scaleY(1);transform-origin:top}55%{transform:scaleY(1);transform-origin:bottom}100%{transform:scaleY(0);transform-origin:bottom}}}
@media (max-width:760px){body.has-hero .site-head{top:0}}
.banner{position:relative;min-height:clamp(460px,74vh,780px);display:flex;align-items:flex-end;color:#fff;background:var(--ink);overflow:hidden}
.banner > img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.banner::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,14,16,.74) 0%,rgba(10,14,16,.42) 45%,rgba(10,14,16,.05) 80%),linear-gradient(180deg,rgba(10,14,16,.5) 0%,rgba(10,14,16,0) 26%,rgba(10,14,16,0) 55%,rgba(10,14,16,.55) 100%)}
.banner .wrap{position:relative;z-index:2;width:100%;padding-bottom:clamp(44px,6vw,84px);padding-top:150px}
.banner h1{max-width:17ch;font-size:clamp(2.5rem,1.6rem + 3.6vw,5rem)}
.banner .lede{color:#E6E9E7}
.banner .crumbs{color:rgba(255,255,255,.82)}
.banner .credit{position:absolute;right:var(--gutter);bottom:16px;z-index:2;font-size:.72rem;opacity:.78}
@media (max-width:760px){.banner::after{background:linear-gradient(180deg,rgba(10,14,16,.5) 0%,rgba(10,14,16,.25) 30%,rgba(10,14,16,.65) 62%,rgba(10,14,16,.9) 100%)}
.banner .credit{bottom:10px;left:var(--gutter);text-align:right;font-size:.64rem;opacity:.7}}
.crumbs{font-size:var(--s--1);color:var(--ink-soft);margin-bottom:24px}
.crumbs a{text-decoration:none}
.crumbs a:hover{text-decoration:underline}
.crumbs span[aria-hidden]{margin:0 .5em;opacity:.6}
.split{display:grid;grid-template-columns:5fr 7fr;gap:clamp(32px,6vw,100px);align-items:start}
.split > *{min-width:0}
@media (max-width:900px){.split,.head-row{grid-template-columns:1fr}}
.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));border-top:1px solid var(--line);margin:0}
.facts div{padding:18px 18px 18px 0;border-bottom:1px solid var(--line)}
.facts dt{font-size:var(--s--1);color:var(--ink-soft)}
.facts dd{margin:4px 0 0;font-weight:500}
.area-list{columns:3 260px;column-gap:clamp(24px,4vw,64px);list-style:none;padding:0;margin:0}
.area-list li{break-inside:avoid;padding:16px 0;border-top:1px solid var(--line)}
.area-list a{text-decoration:none;font-family:var(--serif);font-size:var(--s-2)}
.area-list a:hover{color:var(--brass)}
.area-list span{display:block;font-size:var(--s--1);color:var(--ink-soft)}
.area-list--thumbs li{position:relative;padding:16px 0 16px 128px;min-height:118px}
.area-list--thumbs .area-thumb{position:absolute;left:0;top:16px;width:112px;height:84px;overflow:hidden;background:var(--stone-2)}
.area-list--thumbs .area-thumb img{width:100%;height:100%;object-fit:cover}
.area-credit{display:block;font-size:.7rem;color:var(--ink-soft);margin-top:4px}
.on-record{border-top:1px solid var(--line-dark);margin-top:56px;padding-top:24px;display:grid;grid-template-columns:auto 1fr;gap:12px clamp(24px,4vw,56px);align-items:baseline}
.on-record h3{font-family:var(--sans);font-size:var(--s--2);font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#fff;margin:0}
.on-record dl{display:flex;flex-wrap:wrap;gap:10px clamp(20px,3vw,40px);margin:0;font-size:.8rem;line-height:1.5}
.on-record dt{color:#97A09C;font-size:.72rem;letter-spacing:.06em;text-transform:uppercase}
.on-record dd{margin:2px 0 0;color:#C2C8C5}
@media (max-width:760px){.on-record{grid-template-columns:1fr}
.on-record dl{display:grid;grid-template-columns:1fr 1fr}}
@media (max-width:420px){.on-record dl{grid-template-columns:1fr}}
.on-record + .legal{margin-top:24px}
.action-bar{position:fixed;right:max(18px,env(safe-area-inset-right,0px));bottom:max(18px,env(safe-area-inset-bottom,0px));z-index:90;display:flex}
.action-bar a{display:inline-flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;color:#fff;min-height:48px}
.action-bar svg{width:18px;height:18px;flex:0 0 18px}
.action-bar span{line-height:1.2;text-align:center}
.action-bar .ab-wa{background:#25603F;padding:12px 18px;border-radius:999px;font-size:.88rem;box-shadow:0 10px 28px rgba(10,14,16,.28);transition:background .25s}
.action-bar .ab-wa:hover{background:var(--ink);color:#fff}
.action-bar .ab-call,.action-bar .ab-brief{display:none}
@media (max-width:760px){body{padding-bottom:calc(60px + env(safe-area-inset-bottom,0px))}
.action-bar{left:0;right:0;bottom:0;display:grid;grid-template-columns:1fr 1fr 1.25fr;background:var(--ink);border-top:1px solid var(--line-dark);padding-bottom:env(safe-area-inset-bottom,0px);box-shadow:0 -8px 24px rgba(10,14,16,.18)}
.action-bar a,.action-bar .ab-call,.action-bar .ab-brief{display:flex;min-height:60px;padding:8px 6px;font-size:.86rem;font-weight:500;border-radius:0;box-shadow:none;background:transparent}
.action-bar a + a{border-left:1px solid var(--line-dark)}
.action-bar .ab-wa{background:transparent}
.action-bar .ab-brief{background:#fff;color:var(--ink)}
.action-bar a:hover,.action-bar a:active{background:var(--slate-2);color:#fff}
.action-bar .ab-brief:hover,.action-bar .ab-brief:active{background:var(--brass-light);color:var(--ink)}
body.nav-open .action-bar{display:none}}
.js .reveal{clip-path:inset(0 0 8% 0);opacity:.001;transform:translateY(24px);transition:clip-path 1.1s var(--ease),opacity .9s var(--ease),transform 1.1s var(--ease)}
.js .reveal.in{clip-path:inset(0 0 0 0);opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}
*,*::before,*::after{animation:none!important;transition:none!important}
.js .reveal{clip-path:none;opacity:1;transform:none}
.btn:active{transform:none}}
@media (max-width:760px){.utility{display:none}
body.has-hero .site-head{top:0}}
.langs ul{display:flex;gap:14px;list-style:none;margin:0;padding:0}
.langs a{text-decoration:none;opacity:.75}
.langs a[aria-current]{opacity:1;color:var(--brass-light)}
.utility .langs{padding-inline-end:22px;border-inline-end:1px solid rgba(255,255,255,.18)}
.langs--nav{display:none}
@media (max-width:1200px){.utility .u-left{display:none}
.utility .wrap{justify-content:flex-end}}
@media (max-width:1100px){.langs--nav{display:block;margin-top:28px;padding-top:18px;border-top:1px solid var(--line)}
.langs--nav ul{flex-wrap:wrap;gap:10px 18px}
.langs--nav a{opacity:1;font-size:.95rem}
.langs--nav a[aria-current]{color:var(--brass);font-weight:600}}
