html[lang="ru"]{--serif:"Noto Serif Display","Noto Serif",Georgia,serif;--sans:"Golos Text","Segoe UI",Arial,sans-serif}
html[lang="zh-Hans"]{--serif:"Songti SC","STSong","Noto Serif CJK SC","Source Han Serif SC","SimSun",serif;--sans:"PingFang SC","Microsoft YaHei","Noto Sans CJK SC","Source Han Sans SC",sans-serif}
