.cookie-banner{position:fixed;z-index:95;inset-inline:max(16px,env(safe-area-inset-left,0px));inset-inline-end:auto;bottom:max(18px,env(safe-area-inset-bottom,0px));max-width:min(520px,calc(100% - 32px));background:var(--ink);color:#DCE1DE;border:1px solid var(--line-dark);box-shadow:0 14px 36px rgba(10,14,16,.32);opacity:0;transform:translateY(12px);transition:opacity .3s var(--ease),transform .3s var(--ease)}
