.cookie-banner__p{font-size:var(--s--1);line-height:1.55;margin:0 0 14px}
.cookie-banner a{color:#fff;text-decoration:underline;text-decoration-color:var(--brass-light);text-underline-offset:3px}
.cookie-banner__acts{display:flex;flex-wrap:wrap;gap:10px}
.cookie-banner .btn{background:#fff;color:var(--ink);border-color:#fff;min-height:44px;padding:.65em 1.2em}
