:root{--white:#FFFFFF;
  --stone:#F2F0EB;
  --stone-2:#E4E1D9;
  --ink:#151C1F;
  --slate:#1C2629;
  --slate-2:#26343A;
  --ink-soft:#4A5357;
  --muted-dark:#A9B1AF;
  --brass:#7A5C2C;
  --brass-light:#CFAE72;
  --line:rgba(21,28,31,.13);
  --line-dark:rgba(255,255,255,.16);
  --serif:"Instrument Serif","Iowan Old Style","Palatino Linotype",Georgia,serif;
  --sans:"Instrument Sans","Helvetica Neue",Helvetica,Arial,sans-serif;
  --measure:66ch;
  --gutter:max(20px,4.5vw);
  --max:1400px;
  --s--2:.78rem;
  --s--1:clamp(.84rem,.82rem + .08vw,.9rem);
  --s-0:clamp(1rem,.98rem + .12vw,1.07rem);
  --s-1:clamp(1.18rem,1.1rem + .35vw,1.38rem);
  --s-2:clamp(1.55rem,1.35rem + .8vw,2.05rem);
  --s-3:clamp(2rem,1.6rem + 1.6vw,3rem);
  --s-4:clamp(2.5rem,1.8rem + 2.9vw,4.3rem);
  --s-5:clamp(2.9rem,1.9rem + 4.2vw,5.6rem);
  --ease:cubic-bezier(.2,.65,.2,1);}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--white);color:var(--ink);font-family:var(--sans);font-size:var(--s-0);line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
img,video{display:block;max-width:100%;height:auto}
a{color:inherit;text-decoration-thickness:1px;text-underline-offset:.25em}
