@media (max-width:760px){.banner::after{background:linear-gradient(-180deg,rgba(10,14,16,.5) 0%,rgba(10,14,16,.25) 30%,rgba(10,14,16,.65) 62%,rgba(10,14,16,.9) 100%)}
