.btn--ghost:hover{background:var(--ink);border-color:var(--ink);color:#fff}
body.has-hero .site-head:not(.stuck) .btn{background:#fff;color:var(--ink);border-color:#fff}
.menu-toggle{display:none;background:none;border:1px solid currentColor;color:inherit;min-height:44px;padding:0 16px;font:inherit;font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}
.menu-close{display:none}
