@font-face{font-family:"Instrument Serif";src:url(/assets/fonts/iserif-400.woff2) format("woff2");font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:"Instrument Serif";src:url(/assets/fonts/iserif-400i.woff2) format("woff2");font-weight:400;font-style:italic;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url(/assets/fonts/instrument-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url(/assets/fonts/instrument-500.woff2) format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url(/assets/fonts/instrument-600.woff2) format("woff2");font-weight:600;font-display:swap}
:root{--white:#FFFFFF;
  --stone:#F2F0EB;
  --stone-2:#E4E1D9;
  --ink:#151C1F;
  --slate:#1C2629;
  --slate-2:#26343A;
  --ink-soft:#4A5357;
  --muted-dark:#A9B1AF;
  --brass:#7A5C2C;
  --brass-light:#CFAE72;
  --line:rgba(21,28,31,.13);
  --line-dark:rgba(255,255,255,.16);
  --serif:"Instrument Serif","Iowan Old Style","Palatino Linotype",Georgia,serif;
  --sans:"Instrument Sans","Helvetica Neue",Helvetica,Arial,sans-serif;
  --measure:66ch;
  --gutter:max(20px,4.5vw);
  --max:1400px;
  --s--2:.78rem;
  --s--1:clamp(.84rem,.82rem + .08vw,.9rem);
  --s-0:clamp(1rem,.98rem + .12vw,1.07rem);
  --s-1:clamp(1.18rem,1.1rem + .35vw,1.38rem);
  --s-2:clamp(1.55rem,1.35rem + .8vw,2.05rem);
  --s-3:clamp(2rem,1.6rem + 1.6vw,3rem);
  --s-4:clamp(2.5rem,1.8rem + 2.9vw,4.3rem);
  --s-5:clamp(2.9rem,1.9rem + 4.2vw,5.6rem);
  --ease:cubic-bezier(.2,.65,.2,1);}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--white);color:var(--ink);font-family:var(--sans);font-size:var(--s-0);line-height:1.65;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
img,video{display:block;max-width:100%;height:auto}
a{color:inherit;text-decoration-thickness:1px;text-underline-offset:.25em}
a:hover{color:var(--brass)}
:focus-visible{outline:2px solid var(--brass);outline-offset:3px}
.dark :focus-visible,.band-dark :focus-visible,.hero :focus-visible,.banner :focus-visible,.cta-band :focus-visible,.site-foot :focus-visible,.utility :focus-visible,.aside-card :focus-visible,body.has-hero .site-head:not(.stuck) :focus-visible,.action-bar :focus-visible{outline-color:var(--brass-light)}
.door:focus-visible,.mosaic a:focus-visible,.work-card:focus-visible,.svc-card:focus-visible,.post-card:focus-visible{outline-offset:4px}
.door:focus-visible img,.work-card:focus-visible img,.svc-card:focus-visible img,.post-card:focus-visible img{transform:scale(1.03)}
::selection{background:var(--brass-light);color:var(--ink)}
.skip{position:absolute;right:0;top:0;transform:translateY(-120%);background:var(--ink);color:#fff;padding:.7rem 1rem;z-index:300}
.skip:focus{right:1rem;top:1rem;transform:none}
h1,h2,h3{font-family:var(--serif);font-weight:400;line-height:1.06;letter-spacing:-.012em;margin:0 0 .45em;text-wrap:balance}
h1{font-size:var(--s-5)}
h2{font-size:var(--s-4)}
h4{font-family:var(--sans);font-size:var(--s-0);font-weight:600;margin:0 0 .4em}
p,ul,ol{margin:0 0 1.1em}
p,li,figcaption,.lede{text-wrap:pretty}
h1,h2,h3{font-kerning:normal;font-variant-ligatures:common-ligatures}
.lede{font-size:var(--s-1);line-height:1.55;max-width:48ch;color:var(--ink-soft)}
.muted{color:var(--ink-soft)}
.small{font-size:var(--s--1)}
.prose{max-width:var(--measure)}
.prose h2{font-size:var(--s-3);margin-top:1.6em;margin-bottom:.5em}
.prose h2 + p,.prose h3 + p{margin-top:0}
.prose p,.prose li{line-height:1.7}
.wrap{max-width:var(--max);margin:0 auto;padding-right:var(--gutter);padding-left:var(--gutter)}
.section{padding-block:clamp(80px,10vw,150px)}
.section--tight{padding-block:clamp(44px,6vw,84px)}
.utility{background:var(--ink);color:#C9CFCC;font-size:var(--s--2);letter-spacing:.01em}
.utility .wrap{display:flex;justify-content:space-between;gap:16px;align-items:center;min-height:36px}
.utility a{text-decoration:none;color:#E8EBE9}
.utility a:hover{color:var(--brass-light)}
.utility .u-right{display:flex;gap:22px}
@media (max-width:760px){.utility .u-left{display:none}
.utility .wrap{justify-content:center}}
.site-head{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.97);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);transition:background .3s}
.site-head .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:82px}
body.has-hero .site-head{position:absolute;right:0;left:0;top:36px;background:linear-gradient(-180deg,rgba(10,14,16,.55),rgba(10,14,16,0));border-bottom-color:rgba(255,255,255,.18);backdrop-filter:none;color:#fff}
