.nav > ul > li{position:relative}
.nav > ul > li > a,.nav > ul > li > button{font:inherit;font-size:.8rem;font-weight:500;letter-spacing:.12em;text-transform:uppercase;text-decoration:none;background:none;border:0;color:inherit;cursor:pointer;padding:28px 0;display:block}
.nav > ul > li > a[aria-current="page"]{box-shadow:inset 0 -2px 0 var(--brass)}
.nav .btn{font-size:.8rem;letter-spacing:.1em;text-transform:uppercase}
.mega{position:absolute;right:50%;top:100%;transform:translateX(30%);width:min(860px,90vw);background:#fff;color:var(--ink);border:1px solid var(--line);box-shadow:0 24px 60px rgba(10,14,16,.14);display:grid;grid-template-columns:1fr 1fr 240px;gap:0 28px;padding:28px;opacity:0;visibility:hidden;transition:opacity .2s,visibility .2s}
.has-mega:hover .mega,.has-mega:focus-within .mega{opacity:1;visibility:visible}
.mega h4{font-size:var(--s--2);font-weight:600;color:var(--brass);margin:0 0 10px;letter-spacing:.02em}
.mega ul{list-style:none;margin:0 0 6px;padding:0}
.mega li a{display:block;padding:7px 0;text-decoration:none;font-size:.95rem;border-bottom:1px solid var(--line)}
.mega .mega-feature{background:var(--stone);display:block;text-decoration:none}
.mega .mega-feature img{width:100%;aspect-ratio:4/3;object-fit:cover}
.mega .mega-feature span{display:block;padding:12px 14px;font-size:.9rem;line-height:1.4}
.mega .mega-feature .mega-credit{display:block;padding:8px 14px 0;font-size:.75rem;line-height:1.35;color:var(--ink-soft)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.6em;min-height:48px;padding:.8em 1.5em;border:1px solid var(--ink);background:var(--ink);color:#fff;text-decoration:none;font-weight:500;font-size:.93rem;border-radius:0;cursor:pointer;font-family:var(--sans);transition:background .25s,border-color .25s,color .25s}
.btn:hover{background:var(--brass);border-color:var(--brass);color:#fff}
.btn:active{transform:translateY(1px)}
.btn.is-sending{opacity:.65;pointer-events:none}
.btn--ghost{background:transparent;color:inherit;border-color:currentColor}
.btn--ghost:hover{background:var(--ink);border-color:var(--ink);color:#fff}
body.has-hero .site-head:not(.stuck) .btn{background:#fff;color:var(--ink);border-color:#fff}
.menu-toggle{display:none;background:none;border:1px solid currentColor;color:inherit;min-height:44px;padding:0 16px;font:inherit;font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;cursor:pointer}
.menu-close{display:none}
@media (max-width:1100px){.site-head{backdrop-filter:none}
.menu-toggle{display:inline-block}
.nav{position:fixed;inset:0 0 0 auto;width:min(420px,100%);background:#fff;color:var(--ink);flex-direction:column;align-items:stretch;padding:96px var(--gutter) 40px;overflow-y:auto;transform:translateX(-100%);transition:transform .35s var(--ease);box-shadow:20px 0 60px rgba(0,0,0,.15)}
.nav.open{transform:none}
.nav > ul{flex-direction:column;align-items:stretch;gap:0}
.nav > ul > li > a,.nav > ul > li > button{padding:14px 0;border-bottom:1px solid var(--line);width:100%;text-align:right}
.mega{position:static;transform:none;width:auto;opacity:1;visibility:visible;box-shadow:none;border:0;padding:8px 0 12px;grid-template-columns:1fr;display:none}
.has-mega.open .mega{display:grid}
.mega .mega-feature{display:none}
.nav .btn{margin-top:20px;background:var(--ink)!important;color:#fff!important;border-color:var(--ink)!important}
.menu-close{display:block}}
.menu-close{position:absolute;top:26px;left:var(--gutter);background:none;border:1px solid var(--line);min-height:44px;padding:0 14px;font:inherit;cursor:pointer}
.hero-video.on{opacity:1;visibility:visible;transition:opacity 1.6s var(--ease)}
@media (prefers-reduced-motion:no-preference){@keyframes xfade{0%{opacity:0}2.4%{opacity:1}20%{opacity:1}22.4%{opacity:0}100%{opacity:0}}
@keyframes drift{0%{transform:scale(1.06)}22.4%{transform:scale(1)}100%{transform:scale(1)}}
@keyframes rise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
@keyframes cue{0%{transform:scaleY(0);transform-origin:top}45%{transform:scaleY(1);transform-origin:top}55%{transform:scaleY(1);transform-origin:bottom}100%{transform:scaleY(0);transform-origin:bottom}}}
